  var v_b: f32 = b_matrices[(v_m + u32(4i))];
  var v_c: f32 = b_matrices[(v_m + u32(8i))];
  var v_d: f32 = b_matrices[(v_m + u32(1i))];
  var v_e: f32 = b_matrices[(v_m + u32(5i))];
  var v_f: f32 = b_matrices[(v_m + u32(9i))];
  var v_g: f32 = b_matrices[(v_m + u32(2i))];
