  } else {
    cw_tmp_1 = 0.0f;
  }
  var v_inverse: f32 = cw_tmp_1;
  var v_nx: f32 = ((((((v_e * v_j) - (v_f * v_h)) * v_normal[0i]) + (((v_f * v_g) - (v_d * v_j)) * v_normal[1i])) + (((v_d * v_h) - (v_e * v_g)) * v_normal[2i])) * v_inverse);
